// PRODUCT OF ARRAY EXCEPT SELF — the trickiest of the 10
// O(n) time, O(1) extra space (output array doesn't count)
function productExceptSelf(nums) {
    const n = nums.length;
    const output = new Array(n).fill(1);

    // Pass 1: output[i] = product of all elements LEFT of i
    let prefix = 1;
    for (let i = 0; i < n; i++) {
        output[i] = prefix;
        prefix *= nums[i]; // update after storing
    }

    // Pass 2: multiply by product of all elements RIGHT of i
    let suffix = 1;
    for (let i = n - 1; i >= 0; i--) {
        output[i] *= suffix;
        suffix *= nums[i]; // update after multiplying
    }

    return output;
}
// [1,2,3,4]: prefix pass -> [1,1,2,6]. suffix pass -> [24,12,4,1]
// Wait: let's trace
// prefix: i=0: out[0]=1, prefix=1. i=1: out[1]=1, prefix=2.
//         i=2: out[2]=2, prefix=6. i=3: out[3]=6, prefix=24.
// After prefix: [1, 1, 2, 6]
// suffix: i=3: out[3]=6*1=6, suffix=4. i=2: out[2]=2*4=8, suffix=12.
//         i=1: out[1]=1*12=12, suffix=24. i=0: out[0]=1*24=24, suffix=24.
// Result: [24, 12, 8, 6] ✓

// LONGEST CONSECUTIVE SEQUENCE — O(n) with hash set trick
function longestConsecutive(nums) {
    const numSet = new Set(nums);
    let maxLen = 0;
    for (const num of numSet) {
        // Only start counting from the BEGINNING of a sequence
        if (!numSet.has(num - 1)) { // num is a sequence start
            let curr = num, len = 1;
            while (numSet.has(curr + 1)) { curr++; len++; }
            maxLen = Math.max(maxLen, len);
        }
    }
    return maxLen;
}
// [100,4,200,1,3,2]: starts at 1 -> 1,2,3,4 len=4, starts at 100 len=1, starts at 200 len=1
// Why O(n): each number is the start of at most one sequence; each number counted at most twice

