// TRAPPING RAIN WATER — two-pointer O(n) O(1)
function trap(height) {
    let left = 0, right = height.length - 1;
    let maxLeft = 0, maxRight = 0;
    let water = 0;

    while (left < right) {
        if (height[left] < height[right]) {
            // Left side is the bottleneck
            if (height[left] >= maxLeft) maxLeft = height[left];
            else water += maxLeft - height[left]; // trapped water at left
            left++;
        } else {
            // Right side is the bottleneck
            if (height[right] >= maxRight) maxRight = height[right];
            else water += maxRight - height[right]; // trapped water at right
            right--;
        }
    }
    return water;
}
// [0,1,0,2,1,0,1,3,2,1,2,1] -> 6

// LONGEST REPEATING CHARACTER REPLACEMENT — O(n)
function characterReplacement(s, k) {
    const count = new Array(26).fill(0);
    let maxCount = 0; // max frequency of any char in current window
    let left = 0, maxLen = 0;

    for (let right = 0; right < s.length; right++) {
        count[s.charCodeAt(right) - 65]++;
        maxCount = Math.max(maxCount, count[s.charCodeAt(right) - 65]);
        // Window valid if: windowSize - maxCount <= k (replacements needed)
        while ((right - left + 1) - maxCount > k) {
            count[s.charCodeAt(left) - 65]--;
            left++;
            // Note: maxCount may now be stale but never overstated
            // This is fine: if maxCount is stale, we won't extend the window
        }
        maxLen = Math.max(maxLen, right - left + 1);
    }
    return maxLen;
}
// 'AABABBA', k=1 -> 4 ('AABA' -> replace B -> 'AAAA')

// 3SUM DEDUPLICATION — the three skip locations
function threeSum(nums) {
    nums.sort((a, b) => a - b);
    const result = [];
    for (let i = 0; i < nums.length - 2; i++) {
        if (i > 0 && nums[i] === nums[i-1]) continue; // skip outer dup
        let left = i + 1, right = nums.length - 1;
        while (left < right) {
            const sum = nums[i] + nums[left] + nums[right];
            if (sum === 0) {
                result.push([nums[i], nums[left], nums[right]]);
                while (left < right && nums[left] === nums[left+1]) left++;  // skip left dup
                while (left < right && nums[right] === nums[right-1]) right--; // skip right dup
                left++; right--;
            } else if (sum < 0) left++;
            else right--;
        }
    }
    return result;
}

