// EVALUATE REVERSE POLISH NOTATION — operand stack
function evalRPN(tokens) {
    const stack = [];
    const ops = {'+': (a,b)=>a+b, '-': (a,b)=>a-b,
                 '*': (a,b)=>a*b, '/': (a,b)=>Math.trunc(a/b)};
    for (const t of tokens) {
        if (ops[t]) {
            const b = stack.pop(), a = stack.pop();
            stack.push(ops[t](a, b)); // a op b: a was pushed first
        } else {
            stack.push(Number(t));
        }
    }
    return stack[0];
}
// ['2','1','+','3','*'] -> (2+1)*3 = 9
// Note: b=stack.pop() first (top), a=stack.pop() second (below)
// For subtraction: 5 2 - means 5-2=3, so a=5 (pushed first), b=2

// GENERATE PARENTHESES — backtracking
function generateParenthesis(n) {
    const result = [];
    function backtrack(current, open, close) {
        if (current.length === 2 * n) {
            result.push(current);
            return;
        }
        if (open < n)  backtrack(current + '(', open + 1, close);
        if (close < open) backtrack(current + ')', open, close + 1);
    }
    backtrack('', 0, 0);
    return result;
}
// n=3: ['((()))','(()())','(())()','()(())','()()()']
// Rule: add '(' if open < n; add ')' if close < open

// REORDER LIST — three techniques combined
function reorderList(head) {
    // Step 1: find middle (fast-slow pointer)
    let slow = head, fast = head;
    while (fast.next && fast.next.next) { slow=slow.next; fast=fast.next.next; }
    // Step 2: reverse second half
    let prev = null, curr = slow.next;
    slow.next = null; // cut list
    while (curr) { const next=curr.next; curr.next=prev; prev=curr; curr=next; }
    // Step 3: interleave
    let first = head, second = prev;
    while (second) {
        const t1=first.next, t2=second.next;
        first.next=second; second.next=t1;
        first=t1; second=t2;
    }
}

