// WORD LADDER — BFS on implicit word graph O(n * L^2 * 26)
function ladderLength(beginWord, endWord, wordList) {
    const wordSet = new Set(wordList);
    if (!wordSet.has(endWord)) return 0;

    const queue = [[beginWord, 1]]; // [word, steps]
    const visited = new Set([beginWord]);

    while (queue.length) {
        const [word, steps] = queue.shift();

        // Try all single-character substitutions
        for (let i = 0; i < word.length; i++) {
            for (let c = 97; c <= 122; c++) { // 'a' to 'z'
                const next = word.slice(0,i) + String.fromCharCode(c) + word.slice(i+1);
                if (next === endWord) return steps + 1;
                if (wordSet.has(next) && !visited.has(next)) {
                    visited.add(next);
                    queue.push([next, steps + 1]);
                }
            }
        }
    }
    return 0; // no path found
}

// DP PREVIEW: CLIMBING STAIRS — memoisation from Module 5
// f(n) = f(n-1) + f(n-2), base: f(1)=1, f(2)=2
function climbStairs(n, memo = new Map()) {
    if (n <= 2) return n;
    if (memo.has(n)) return memo.get(n);
    const result = climbStairs(n-1, memo) + climbStairs(n-2, memo);
    memo.set(n, result);
    return result;
}

